few_shot_examples.query:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "fire") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "fire")
  )
}
ORDER BY ?attribute

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT
  ?hazard
  ?hazardName
  ?hazardType
  ?fireType
  ?place
  ?startDate
  ?endDate
  ?affectedArea
  ?deaths
  ?damageToCrops
  ?damageToInfrastructure
WHERE {
  ?hazard a kwgl-ont:HazardEvent .

  {
    ?hazard a kwgl-ont:Fire .
  }
  UNION {
    ?hazard kwgl-ont:hasHazardType ?hazardType .
    VALUES ?hazardType { kwglr:fire kwglr:wildfire }
  }

  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?hazard kwgl-ont:isOfFireType ?fireType . }
  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName . }
  OPTIONAL { ?hazard kwgl-ont:hasImpacted ?place . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
}
ORDER BY ?hazardType ?fireType ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  FILTER(
    CONTAINS(LCASE(STR(?attribute)), "landslide") ||
    (BOUND(?attributeLabel) && CONTAINS(LCASE(STR(?attributeLabel)), "landslide"))
  )

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT
  ?hazard
  ?place
  ?placeName
  ?startDate
  ?endDate
  ?damageAttribute
  ?damageValue
  ?range
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType kwglr:flood ;
          kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }

  ?damageAttribute rdf:type owl:DatatypeProperty ;
                   rdfs:domain kwgl-ont:Place .

  FILTER(
    CONTAINS(LCASE(STR(?damageAttribute)), "flood")
  )

  ?place ?damageAttribute ?damageValue .

  OPTIONAL { ?damageAttribute rdfs:range ?range . }
}
ORDER BY ?hazard ?damageAttribute ?place

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazard
  ?hazardType
  ?place
  ?placeName
  ?startDate
  ?endDate
  ?damageAttribute
  ?damageLabel
  ?damageValue
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType ?hazardType ;
          kwgl-ont:hasImpacted ?place .

  FILTER(CONTAINS(LCASE(STR(?hazardType)), "landslide"))

  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }

  ?damageAttribute rdf:type owl:DatatypeProperty ;
                   rdfs:domain kwgl-ont:Place .

  OPTIONAL { ?damageAttribute rdfs:label ?damageLabel . }

  FILTER(
    CONTAINS(LCASE(STR(?damageAttribute)), "landslide") ||
    (BOUND(?damageLabel) && CONTAINS(LCASE(STR(?damageLabel)), "landslide"))
  )

  ?place ?damageAttribute ?damageValue .
}
ORDER BY ?hazard ?place ?damageAttribute

